import{c as e,Q as a,j as o,m as r}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Goals","description":"","frontmatter":{},"headers":[],"relativePath":"guide/goals.md","filePath":"guide/goals.md","lastUpdated":null}'),n={name:"guide/goals.md"};function i(s,t,l,d,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h1><p>Targets you can contribute to, with a built-in compound-growth projection.</p><h2 id="creating-a-goal" tabindex="-1">Creating a goal <a class="header-anchor" href="#creating-a-goal" aria-label="Permalink to &quot;Creating a goal&quot;">​</a></h2><ol><li><strong>Goals → New goal</strong> — name, target amount, optional deadline.</li><li>Pick a funding account (contributions are transactions into the goal bucket).</li><li>The card shows contributed / target, remaining, and a thin progress bar. Emergency-fund goals offer a quick-fill button tied to <code>wellness_context.emergency_fund_months</code>.</li></ol><h2 id="contributions" tabindex="-1">Contributions <a class="header-anchor" href="#contributions" aria-label="Permalink to &quot;Contributions&quot;">​</a></h2><p>Record a transaction categorized to the goal’s bucket or use <strong>Contribute</strong> on the goal card — both are the same ledger rows with a goal linkage (<code>repos/goals</code>). History is shown on the card.</p><h2 id="projections" tabindex="-1">Projections <a class="header-anchor" href="#projections" aria-label="Permalink to &quot;Projections&quot;">​</a></h2><p>The what-if projection computes 10/20/30-year wealth from the current contribution rate at <strong>7% annual</strong> (Hill / Kiyosaki) and renders it on the goal. It is deterministic arithmetic, not a prediction — the Copilot is instructed to say so. Change the monthly amount to see the long-range effect instantly.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>How FinSight treats it</th></tr></thead><tbody><tr><td>Emergency fund</td><td>Quick-fill offered; months-of-cover gauge derived from expenses</td></tr><tr><td>Debt payoff</td><td>Ordered smallest-balance-first for the snowball; see also <a href="/FinSight/guide/journey">Journey</a></td></tr><tr><td>Saving / Investment</td><td>Long-range projection rendered; conscious-spending type is Saving or Investment</td></tr></tbody></table><h2 id="what-if" tabindex="-1">What-if <a class="header-anchor" href="#what-if" aria-label="Permalink to &quot;What-if&quot;">​</a></h2><p>The goal screen’s what-if grid lets you compare “what if I add $200/month for 12 months?” across horizons without writing a scenario. For richer “what if I move house / change jobs” questions, use <a href="/FinSight/guide/scenarios">Scenarios</a>.</p><p>See also: <a href="/FinSight/guide/budget">Budget</a>, <a href="/FinSight/framework/overview">Financial Framework</a>.</p>',13)])])}const f=e(n,[["render",i]]);export{u as __pageData,f as default};
